#!/usr/bin/env python3
"""values-of-another-realm.py <folder>: ONE CASE A FOLDER: VALUES OF ANOTHER REALM (node:vm contexts, ShadowRealm) IN COMPILED, TYPED CODE. The built-ins of such a context are its own AND MUTABLE: an array, a Map, a Promise, a plain object made there has another prototype, which the context's code may have patched: whatever compiled code does in place for "an array", "a Map", "a promise" must not be done to these, or must give what plain Bun gives. And the other way: typed objects and compiled functions handed into a context."""
import os, sys
out = sys.argv[1]; cases = {}
H = 'declare const console: { log(...v: unknown[]): void }; declare const require: any; declare const ShadowRealm: any;\nconst vm = require("node:vm");\nconst show = (v: unknown): string => { try { return typeof v === "string" ? v : typeof v === "function" ? "function" : typeof v === "symbol" ? v.toString() : JSON.stringify(v) ?? String(v); } catch (e) { return "unshowable " + (e as Error).name; } };\nconst row = (name: string, f: () => unknown): void => { let t: string; try { t = show(f()); } catch (e) { t = "THROWS " + ((e as any)?.name ?? typeof e) + ": " + String((e as any)?.message).split("\\n")[0].slice(0, 70); } console.log(name + ": " + t); };\nconst ctx = vm.createContext({});\nconst there = (code: string): any => vm.runInContext(code, ctx);\n'
def case(name, body): cases[name] = {"main.ts": H + body + "\n"}
ARR = '''function uses(xs: number[]): string[] { const r: string[] = []; const t = (n: string, f: () => unknown): void => { try { r.push(n + "=" + show(f())); } catch (e) { r.push(n + "!" + (e as Error).name); } };
  t("length", () => xs.length); t("index", () => xs[1]); t("map", () => xs.map(x => x + 1)); t("filter", () => xs.filter(x => x > 1)); t("forEach", () => { let s = 0; xs.forEach(x => { s += x; }); return s; }); t("for of", () => { let s = 0; for (const x of xs) s += x; return s; }); t("for", () => { let s = 0; for (let i = 0; i < xs.length; i++) s += xs[i]!; return s; });
  t("spread", () => [...xs]); t("destructure", () => { const [a, b] = xs; return [a, b]; }); t("rest", () => { const [, ...rest] = xs; return rest; }); t("join", () => xs.join("-")); t("includes", () => xs.includes(2)); t("indexOf", () => xs.indexOf(3)); t("slice", () => xs.slice(1)); t("concat", () => xs.concat([9])); t("concat into", () => [0].concat(xs)); t("reduce", () => xs.reduce((a, b) => a + b, 0)); t("some", () => xs.some(x => x === 2)); t("find", () => xs.find(x => x > 1)); t("at", () => xs.at(-1)); t("keys", () => [...xs.keys()]); t("entries", () => [...xs.entries()]); t("toString", () => String(xs)); t("template", () => `${xs}`);
  t("isArray", () => Array.isArray(xs)); t("instanceof", () => xs instanceof Array); t("constructor", () => xs.constructor === Array); t("proto", () => Object.getPrototypeOf(xs) === Array.prototype); t("json", () => JSON.stringify(xs)); t("from", () => Array.from(xs)); t("max", () => Math.max(...xs)); t("apply", () => Math.max.apply(null, xs)); t("map is Array", () => xs.map(x => x) instanceof Array); t("slice is Array", () => xs.slice() instanceof Array);
  t("push", () => xs.push(4)); t("pop", () => xs.pop()); t("store", () => { xs[0] = 10; return xs[0]; }); t("grow", () => { xs[5] = 6; return xs.length; }); t("shrink", () => { xs.length = 3; return xs; }); t("sort", () => xs.sort((a, b) => b - a)); t("reverse", () => xs.reverse()); t("splice", () => xs.splice(0, 1)); t("fill", () => xs.fill(7)); return r; }
'''
case("an-array-of-another-realm", ARR + 'for (let i = 0; i < 50; i++) uses([1, 2, 3]);\nconsole.log(uses([1, 2, 3]).join(" ")); console.log(uses(there("[1, 2, 3]")).join(" ")); console.log(uses(there("[1, 2, 3]")).join(" "));')
case("an-array-whose-realm-has-patched-its-methods", ARR + 'there(`for (const k of ["map", "filter", "forEach", "join", "includes", "indexOf", "slice", "concat", "reduce", "some", "find", "at", "push", "pop", "sort", "reverse", "splice", "fill", "keys", "entries", "toString"]) Array.prototype[k] = function () { return "patched " + k; };`);\nfor (let i = 0; i < 50; i++) uses([1, 2, 3]);\nconsole.log(uses(there("[1, 2, 3]")).join(" ")); console.log(uses([1, 2, 3]).join(" "));')
case("an-array-whose-realm-has-patched-its-iterator", ARR + 'there(`Array.prototype[Symbol.iterator] = function* () { yield 100; yield 200; };`);\nfor (let i = 0; i < 50; i++) uses([1, 2, 3]);\nconsole.log(uses(there("[1, 2, 3]")).join(" ")); console.log(uses([1, 2, 3]).join(" "));')
case("an-array-whose-realm-has-elements-on-the-prototype", ARR + 'there(`Array.prototype[1] = 111; Object.prototype[2] = 222;`);\nfor (let i = 0; i < 50; i++) uses([1, 2, 3]);\nconsole.log(uses(there("[1, , , 4]")).join(" ")); console.log(uses(there("const a = [1, 2, 3]; delete a[1]; a")).join(" "));')
MAP = '''function uses(m: Map<string, number>, s: Set<number>): string[] { const r: string[] = []; const t = (n: string, f: () => unknown): void => { try { r.push(n + "=" + show(f())); } catch (e) { r.push(n + "!" + (e as Error).name); } };
  t("get", () => m.get("a")); t("has", () => m.has("a")); t("size", () => m.size); t("set", () => m.set("b", 2) === m); t("for of", () => { let k = ""; for (const [a, b] of m) k += a + b; return k; }); t("forEach", () => { let k = ""; m.forEach((v, a) => { k += a + v; }); return k; }); t("keys", () => [...m.keys()]); t("spread", () => [...m]); t("delete", () => m.delete("b")); t("instanceof", () => m instanceof Map); t("new Map", () => new Map(m).size);
  t("set has", () => s.has(1)); t("set add", () => s.add(2) === s); t("set size", () => s.size); t("set of", () => { let k = 0; for (const x of s) k += x; return k; }); t("set spread", () => [...s]); t("set instanceof", () => s instanceof Set); return r; }
'''
case("a-map-and-a-set-of-another-realm", MAP + 'for (let i = 0; i < 50; i++) uses(new Map([["a", 1]]), new Set([1]));\nconsole.log(uses(there(`new Map([["a", 1]])`), there("new Set([1])")).join(" "));')
case("a-map-and-a-set-whose-realm-has-patched-them", MAP + 'there(`for (const k of ["get", "has", "set", "delete", "forEach", "keys"]) Map.prototype[k] = function () { return "patched " + k; }; for (const k of ["has", "add"]) Set.prototype[k] = function () { return "patched " + k; }; Object.defineProperty(Map.prototype, "size", { get() { return "patched size"; } }); Map.prototype[Symbol.iterator] = function* () { yield ["z", 26]; }; Set.prototype[Symbol.iterator] = function* () { yield 50; };`);\nfor (let i = 0; i < 50; i++) uses(new Map([["a", 1]]), new Set([1]));\nconsole.log(uses(there(`new Map([["a", 1]])`), there("new Set([1])")).join(" ")); console.log(uses(new Map([["a", 1]]), new Set([1])).join(" "));')
case("a-promise-of-another-realm", 'async function uses(p: Promise<number>): Promise<string> { const log: string[] = []; log.push("instanceof " + (p instanceof Promise)); log.push("awaited " + (await p)); log.push("then " + (await p.then(v => v + 1))); log.push("all " + (await Promise.all([p, 2])).join()); log.push("resolve same " + (Promise.resolve(p) === p)); log.push("race " + (await Promise.race([p]))); log.push("finally " + (await p.finally(() => {}))); return log.join(" | "); }\nfor (let i = 0; i < 20; i++) await uses(Promise.resolve(1));\nconsole.log(await uses(there("Promise.resolve(5)"))); there(`Promise.prototype.then = function (f) { return { then(g) { g("by a patched then"); } }; };`); console.log(await uses(there("Promise.resolve(6)")).catch(e => "fails " + e.name)); console.log(await uses(Promise.resolve(7)));')
case("the-order-of-jobs-with-a-promise-of-another-realm", 'const log: string[] = []; const p: Promise<number> = there("Promise.resolve(1)"); const q = Promise.resolve(2);\n(async () => { log.push("a starts"); await p; log.push("a behind the foreign one"); await q; log.push("a behind ours"); })(); (async () => { log.push("b starts"); await q; log.push("b behind ours"); await p; log.push("b behind the foreign one"); })(); Promise.resolve().then(() => log.push("job 1")).then(() => log.push("job 2")).then(() => log.push("job 3")).then(() => log.push("job 4"));\nawait new Promise(r => setTimeout(r, 5)); console.log(log.join(" | "));\ndeclare function setTimeout(f: (v?: unknown) => void, ms: number): unknown;')
OBJ = '''interface Row { a: number; b: string; c?: boolean }
function uses(o: Row): string[] { const r: string[] = []; const t = (n: string, f: () => unknown): void => { try { r.push(n + "=" + show(f())); } catch (e) { r.push(n + "!" + (e as Error).name); } }; const x: any = o;
  t("a", () => o.a); t("b", () => o.b); t("c", () => o.c); t("inherited", () => x.inherited); t("in", () => "inherited" in o); t("for in", () => { let k = ""; for (const n in o) k += n + ","; return k; }); t("keys", () => Object.keys(o)); t("spread", () => ({ ...o })); t("json", () => JSON.stringify(o)); t("toString", () => String(o)); t("hasOwn", () => Object.hasOwn(o, "a")); t("hasOwnProperty", () => x.hasOwnProperty("a")); t("instanceof", () => o instanceof Object); t("proto", () => Object.getPrototypeOf(o) === Object.prototype); t("constructor", () => x.constructor === Object); t("store", () => { o.a = 5; return o.a; }); t("store c", () => { o.c = true; return o.c; }); t("destructure", () => { const { a, ...rest } = o; return [a, rest]; }); t("valueOf", () => x.valueOf() === o); return r; }
'''
case("an-object-of-another-realm", OBJ + 'for (let i = 0; i < 50; i++) uses({ a: 1, b: "b" });\nconsole.log(uses(there(`({ a: 1, b: "b" })`)).join(" "));')
case("an-object-whose-realm-has-patched-object-prototype", OBJ + 'there(`Object.prototype.inherited = "from the context"; Object.prototype.c = "inherited c"; Object.prototype.toString = function () { return "patched toString"; }; Object.prototype.hasOwnProperty = function () { return "patched hasOwnProperty"; }; Object.prototype.toJSON = function () { return "patched toJSON"; };`);\nfor (let i = 0; i < 50; i++) uses({ a: 1, b: "b" });\nconsole.log(uses(there(`({ a: 1, b: "b" })`)).join(" ")); console.log(uses({ a: 1, b: "b" }).join(" "));')
case("other-things-of-another-realm", 'function f(d: Date, re: RegExp, e: Error, fn: (x: number) => number, u: Uint8Array, s: symbol, big: bigint, str: string): string { return [d.getTime(), d instanceof Date, re.test("abc"), re instanceof RegExp, "abc".replace(re, "x"), e.message, e instanceof Error, e.name, fn(2), fn instanceof Function, typeof fn, u.length, u[0], u instanceof Uint8Array, [...u].join(), s.toString(), s === Symbol.for("shared"), big + 1n, str.length, str + "!"].join(); }\nfor (let i = 0; i < 20; i++) f(new Date(5), /b/, new Error("m"), x => x * 2, new Uint8Array([7]), Symbol.for("shared"), 1n, "s");\nrow("all", () => f(there("new Date(5)"), there("/b/"), there(`new RangeError("m")`), there("x => x * 3"), there("new Uint8Array([7, 8])"), there(`Symbol.for("shared")`), there("5n"), there(`"text"`)));\nrow("thrown there", () => there(`null.x`)); row("thrown there, caught here", () => { try { there(`throw new TypeError("from there")`); } catch (e) { return [e instanceof TypeError, e instanceof Error, (e as Error).name, (e as Error).message].join(); } });')
case("typed-things-handed-into-a-context", 'interface Row { a: number; b: string; c?: boolean }\nclass Kept { n = 1; #p = 2; get g(): number { return this.#p; } m(x: number): number { return this.n + x; } }\nconst into = vm.createContext({ row: { a: 1, b: "b" } as Row, kept: new Kept(), list: [1, 2, 3] as number[], add: (x: number, y: number): number => x + y, typed: (r: Row): string => r.a + r.b, map: new Map<string, number>([["a", 1]]) });\nconst run = (code: string): void => row(code, () => vm.runInContext(code, into));\nfor (const code of ["row.a + row.b", "Object.keys(row).join()", "JSON.stringify(row)", "row.c = true; JSON.stringify(row)", "row.a = 5; row.a", `row.a = "wrong"; typeof row.a`, "row.extra = 1; Object.keys(row).join()", "delete row.c; Object.keys(row).join()", "row instanceof Object", "Object.getPrototypeOf(row) === Object.prototype", "for (var k in row) k", "({ ...row }).b", "kept.m(2)", "kept.g", "kept.n = 7; kept.m(0)", "Object.keys(kept).join()", "kept.constructor.name", "list.map(x => x * 2).join()", "list.push(4); list.length", `list.push("wrong"); list.length`, "Array.isArray(list)", "list instanceof Array", "[...list].length", "add(1, 2)", `add("1", 2)`, "add()", "add.call(null, 3, 4)", "add.length + add.name", `typed({ a: 1, b: "x" })`, "typed({ a: 1 })", "typed(row)", "new add(1, 2)", `map.get("a")`, `map.set("b", 2).size`, "Object.freeze(row); Object.isFrozen(row)", "Object.setPrototypeOf(kept, null); typeof kept.m"]) run(code);')
case("a-typed-object-as-the-global-of-a-context", 'interface G { count: number; name: string; extra?: number }\nconst g: G = { count: 1, name: "g" };\nrow("make", () => { vm.createContext(g); return vm.isContext(g); });\nfor (const code of ["count + name", "count = 5; count", "var made = 1; made", "extra = 2; extra", `count = "wrong"; typeof count`, "typeof globalThis.count", "Object.keys(globalThis).join()", "delete globalThis.extra; typeof extra"]) row(code, () => vm.runInContext(code, g));\nrow("seen here", () => [g.count, g.name, g.extra, Object.keys(g).join()].join("|"));')
case("code-run-in-this-context", 'declare const madeThere: number; declare function declaredThere(): string;\nrow("a var", () => { vm.runInThisContext("var madeThere = 5; function declaredThere() { return \'declared there\'; }"); return [typeof madeThere, madeThere, declaredThere()].join(); });\nrow("a patch of a built-in", () => vm.runInThisContext("Array.prototype.last = function () { return 1; }; [].last()"));\nrow("math", () => vm.runInThisContext("Math.random = () => 0.5; Math.random()"));\nrow("same realm", () => vm.runInThisContext("[1, 2]") instanceof Array);\nrow("a script", () => new vm.Script("1 + 1").runInThisContext());\nrow("compile function", () => vm.compileFunction("return a + b", ["a", "b"])(1, 2));\nrow("new context", () => vm.runInNewContext("x + 1", { x: 1 }));')
case("a-shadow-realm", 'row("there is one", () => typeof ShadowRealm);\nif (typeof ShadowRealm === "function") { const realm = new ShadowRealm(); row("a primitive", () => realm.evaluate("1 + 1")); row("a function", () => realm.evaluate("x => x * 2")(4)); row("an object", () => realm.evaluate("({})")); row("a patch there", () => realm.evaluate("Array.prototype.last = function () { return 9; }; [].last()")); row("not here", () => typeof ([] as any).last); row("our function goes in", () => realm.evaluate("f => f(3)")((x: number): number => x + 1)); row("a wrong argument", () => realm.evaluate(`f => f("three")`)((x: number): number => x + 1)); }')
for name, files in cases.items():
    os.makedirs(f"{out}/{name}", exist_ok=True)
    for f, text in files.items(): open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
